def balancedRangeQueries(nums, queries):
    pre = [0]
    for x in nums:
        pre.append(pre[-1] + x)
    where = {v: i for i, v in enumerate(pre)}
    out = []
    for l, r in queries:
        total = pre[r + 1] - pre[l]
        if total % 2:
            out.append(0)
        else:
            out.append(1 if (pre[l] + total // 2) in where else 0)
    return out
